            return scopes;
        }

        /**
         * Get the tenant ID from {@code authorizationUri}.
         */
        String getTenantId() {
            return tenantId;
        }
    }

    /**
     * Clears the challenge cache.
     */
    public static void clearCache() {
        CHALLENGE_CACHE.clear();
    }

    /**
